// === Tab: mySketch ===
let mainCanvas, captureCanvas, captureCtx, gl
let fbo, font, particles, particleShader
let subtitleParticles, subtitleShader
let authorParticles, authorShader

const SUBTITLE       = "UNE EXPERIENCE SENSORIELLE"
const AUTHOR         = "Nousnouss B."
const START_DELAY    = 5000
const SUBTITLE_DELAY = START_DELAY + 7000
const AUTHOR_DELAY   = START_DELAY + 11000

const HUE_PALETTE  = [0, 30, 60, 120, 180, 200, 270, 320]
const HUE_DURATION = 2000
let currentHueS, nextHueS, hueTransitionStartS
let currentHueA, nextHueA, hueTransitionStartA

let mediaRecorder   = null
let recordingChunks = []
let isRecording     = false

function pickNextHue(current) {
  let h
  do { h = random(HUE_PALETTE) } while (h === current)
  return h
}

async function setup() {
  var h = windowHeight
  const w = floor(h * 9 / 16)
  mainCanvas = createCanvas(w, h, WEBGL)


  gl = mainCanvas.elt.getContext('webgl2') || mainCanvas.elt.getContext('webgl')

  captureCanvas        = document.createElement('canvas')
  captureCanvas.width  = w
  captureCanvas.height = h
  captureCtx           = captureCanvas.getContext('2d')

  currentHueS         = random(HUE_PALETTE)
  nextHueS            = pickNextHue(currentHueS)
  hueTransitionStartS = 0
  currentHueA         = random(HUE_PALETTE)
  nextHueA            = pickNextHue(currentHueA)
  hueTransitionStartA = 0

  font = await loadFont('https://fonts.gstatic.com/s/ubuntu/v21/4iCv6KVjbNBYlgoCxCvTt2aMH4V_gg.ttf')

  fbo = createFramebuffer({ width: 170, height: 75, density: 1 })
  fbo.draw(() => {
    background(0); fill(255)
    textFont(font); textAlign(CENTER, CENTER); textSize(27)
    text('ÉCHOLALIE', 0, 0)
  })
  fbo.loadPixels()

  particles = buildGeometry(() => {
    noFill()
    translate(-fbo.width / 2, -fbo.height / 2)
    beginShape(LINES)
    for (let x = 0; x < fbo.width; x++)
      for (let y = 0; y < fbo.height; y++)
        if (fbo.pixels[(y * fbo.width + x) * 4] > 0) { vertex(x, y); vertex(x + 0.001, y) }
    const o = createVector(fbo.width / 2 - 70, fbo.height / 2)
    for (let i = 0; i < 3000; i++) {
      let x = floor(random(-1, 2) * fbo.width), y = floor(random(-1, 2) * fbo.height)
      const r = Math.hypot(x - o.x, y - o.y), theta = Math.atan2(y - o.y, x - o.x)
      const newR = floor(r / 20) * 20 + randomGaussian(0, 4)
      x = floor((o.x + newR * cos(theta)) * 5) / 5
      y = floor((o.y + newR * sin(theta)) * 5) / 5
      vertex(x, y); vertex(x + 0.001, y)
    }
    for (let i = 0; i < 4000; i++) {
      const angle = random(TWO_PI)
      const ringR = (floor(random(2, 30)) * 18) + randomGaussian(0, 5)
      var x     = floor((o.x + ringR * cos(angle)) * 5) / 5
      const y     = floor((o.y + ringR * sin(angle)) * 5) / 5
      vertex(x, y); vertex(x + 0.001, y)
    }
    endShape()
  })

  particleShader = baseStrokeShader().modify(() => {
    const t = uniformFloat(() => max(0, millis() - START_DELAY))
    getObjectInputs((inputs) => {
      const pos       = floor(inputs.position.xy * 5) / 5
      const seed      = pos * Math.PI
      const orig      = [-70, 0]
      const origR     = length(orig - pos)
      const startTime = origR / 50 * 1000
      const endTime   = startTime + 4000
      const progress  = smoothstep(startTime, endTime, t)
      inputs.weight  *= smoothstep(startTime - 1000, endTime + 1000, t) * mix(0.7, 1, 1 - noise(seed))
      inputs.position.xy = mix(
        pos + [200 * (noise(seed.x, seed.y, 1000) - 0.3), 100 * (noise(seed.x, seed.y, 1200) - 0.3)],
        pos, progress)
      const diff = inputs.position.xy - orig
      const dir  = normalize(diff), r = length(diff)
      let frs = 0.2
      if (abs(pos.x) > 75) frs = 1
      if (abs(pos.y) > 15) frs = 1
      inputs.position.xy += mix(2, frs, progress) * sin(r - t * 0.01) * dir
      inputs.position.xy += mix(2, 0.1, progress) * [noise(seed.x, seed.y, t * 0.001), noise(seed.x, seed.y, t * 0.001 + 100)]
      return inputs
    })
  })

  // ── SOUS-TITRE ──────────────────────────────────────────────────────────────
  const sFbo = createFramebuffer({ width: 320, height: 36, density: 1 })
  sFbo.draw(() => {
    background(0); fill(255)
    textFont(font); textAlign(CENTER, CENTER); textSize(12)
    text(SUBTITLE, 0, 0)
  })
  sFbo.loadPixels()

  subtitleParticles = buildGeometry(() => {
    noFill()
    translate(-sFbo.width / 2, -sFbo.height / 2)
    beginShape(LINES)
    for (let x = 0; x < sFbo.width; x++)
      for (let y = 0; y < sFbo.height; y++)
        if (sFbo.pixels[(y * sFbo.width + x) * 4] > 0) { vertex(x, y); vertex(x + 0.001, y) }
    var o = createVector(sFbo.width / 2 + 100, sFbo.height / 2)
    for (let i = 0; i < 3000; i++) {
      var angle = random(TWO_PI)
      var ringR = (floor(random(1, 20)) * 30) + randomGaussian(0, 4)
      var x     = floor((o.x + ringR * cos(angle)) * 5) / 5
      var y     = floor((o.y + ringR * sin(angle)) * 5) / 5
      vertex(x, y); vertex(x + 0.001, y)
    }
    endShape()
  })

  subtitleShader = baseStrokeShader().modify(() => {
    var t = uniformFloat(() => max(0, millis() - SUBTITLE_DELAY))
    getObjectInputs((inputs) => {
      var pos       = floor(inputs.position.xy * 5) / 5
      var seed      = pos * Math.PI
      var orig      = [-40, 0]
      var origR     = length(orig - pos)
      var startTime = origR / 40 * 1000
      var endTime   = startTime + 3000
      var progress  = smoothstep(startTime, endTime, t)
      inputs.weight  *= smoothstep(startTime - 800, endTime + 800, t) * mix(0.5, 0.8, 1 - noise(seed)) * 0.65
      inputs.position.xy = mix(
        pos + [120 * (noise(seed.x, seed.y, 2000) - 0.3), 60 * (noise(seed.x, seed.y, 2200) - 0.3)],
        pos, progress)
      var diff = inputs.position.xy - orig
      var dir  = normalize(diff), r = length(diff)
      var frs = 0.15
      if (abs(pos.x) > 144) frs = 0.8
      if (abs(pos.y) > 14)  frs = 0.8
      inputs.position.xy += mix(1.4, frs, progress) * sin(r - t * 0.012) * dir
      inputs.position.xy += mix(1.4, 0.07, progress) * [noise(seed.x, seed.y, t * 0.001 + 2000), noise(seed.x, seed.y, t * 0.001 + 2100)]
      return inputs
    })
  })

  // ── AUTEUR ──────────────────────────────────────────────────────────────────
  const aFbo = createFramebuffer({ width: 180, height: 28, density: 1 })
  aFbo.draw(() => {
    background(0); fill(255)
    textFont(font); textAlign(CENTER, CENTER); textSize(10)
    text(AUTHOR, 0, 0)
  })
  aFbo.loadPixels()

  authorParticles = buildGeometry(() => {
    noFill()
    translate(-aFbo.width / 2, -aFbo.height / 2)
    beginShape(LINES)
    for (let x = 0; x < aFbo.width; x++)
      for (let y = 0; y < aFbo.height; y++)
        if (aFbo.pixels[(y * aFbo.width + x) * 4] > 0) { vertex(x, y); vertex(x + 0.001, y) }
    var o = createVector(aFbo.width / 2, aFbo.height / 2)
    for (let i = 0; i < 1000; i++) {
      var angle = random(TWO_PI)
      var ringR = (floor(random(1, 8)) * 25) + randomGaussian(0, 3)
      var x     = floor((o.x + ringR * cos(angle)) * 5) / 5
      var y     = floor((o.y + ringR * sin(angle)) * 5) / 5
      vertex(x, y); vertex(x + 0.001, y)
    }
    endShape()
  })

  authorShader = baseStrokeShader().modify(() => {
    var t = uniformFloat(() => max(0, millis() - AUTHOR_DELAY))
    getObjectInputs((inputs) => {
      var pos       = floor(inputs.position.xy * 5) / 5
      var seed      = pos * Math.PI
      var orig      = [-20, 0]
      var origR     = length(orig - pos)
      var startTime = origR / 40 * 1000
      var endTime   = startTime + 3000
      var progress  = smoothstep(startTime, endTime, t)
      inputs.weight  *= smoothstep(startTime - 800, endTime + 800, t) * mix(0.5, 0.8, 1 - noise(seed)) * 0.65
      inputs.position.xy = mix(
        pos + [80 * (noise(seed.x, seed.y, 4000) - 0.3), 40 * (noise(seed.x, seed.y, 4200) - 0.3)],
        pos, progress)
      var diff = inputs.position.xy - orig
      var dir  = normalize(diff), r = length(diff)
      var frs = 0.15
      if (abs(pos.x) > 81) frs = 0.8
      if (abs(pos.y) > 11) frs = 0.8
      inputs.position.xy += mix(1.4, frs, progress) * sin(r - t * 0.012) * dir
      inputs.position.xy += mix(1.4, 0.07, progress) * [noise(seed.x, seed.y, t * 0.001 + 4000), noise(seed.x, seed.y, t * 0.001 + 4100)]
      return inputs
    })
  })
}

function draw() {
  background(0)
  noFill(); stroke(255); strokeWeight(1)
  const s   = min(width / 180, height / 115)
  const now = millis()

  // ── Couleur animée sous-titre ──────────────────────────────────────────────
  const elapsedS = now - hueTransitionStartS
  const tColS    = constrain(elapsedS / HUE_DURATION, 0, 1)
  const easedS   = tColS < 0.5 ? 2*tColS*tColS : -1+(4-2*tColS)*tColS
  let deltaS = nextHueS - currentHueS
  if (deltaS >  180) deltaS -= 360
  if (deltaS < -180) deltaS += 360
  const subtitleColor = color(`hsl(${currentHueS + deltaS * easedS}, 90%, 72%)`)
  if (tColS >= 1) {
    currentHueS         = nextHueS
    nextHueS            = pickNextHue(currentHueS)
    hueTransitionStartS = now
  }

  // ── Couleur animée auteur ──────────────────────────────────────────────────
  const elapsedA = now - hueTransitionStartA
  const tColA    = constrain(elapsedA / HUE_DURATION, 0, 1)
  const easedA   = tColA < 0.5 ? 2*tColA*tColA : -1+(4-2*tColA)*tColA
  let deltaA = nextHueA - currentHueA
  if (deltaA >  180) deltaA -= 360
  if (deltaA < -180) deltaA += 360
  const authorColor = color(`hsl(${currentHueA + deltaA * easedA}, 90%, 72%)`)
  if (tColA >= 1) {
    currentHueA         = nextHueA
    nextHueA            = pickNextHue(currentHueA)
    hueTransitionStartA = now
  }

  // ── Titre ──────────────────────────────────────────────────────────────────
  push()
  translate(0, -height * 0.25)
  scale(s)
  strokeShader(particleShader)
  model(particles)
  pop()

  // ── Sous-titre ────────────────────────────────────────────────────────────
  push()
  translate(s * 18, s * 8)
  scale(s * 0.65)
  stroke(subtitleColor)
  strokeWeight(2.5)
  strokeShader(subtitleShader)
  model(subtitleParticles)
  pop()

  // ── Auteur ────────────────────────────────────────────────────────────────
  push()
  translate(s * 18, height * 0.28)
  scale(s * 0.65)
  stroke(authorColor)
  strokeWeight(2.5)
  strokeShader(authorShader)
  model(authorParticles)
  pop()

  // ── Copie vers canvas 2D capturable ───────────────────────────────────────
  if (isRecording) {
    gl.finish()
    captureCtx.drawImage(mainCanvas.elt, 0, 0)
  }
}

function keyPressed() {
  if (key === 'r' || key === 'R') toggleRecording()
}

function toggleRecording() {
  if (isRecording) {
    if (mediaRecorder && mediaRecorder.state !== 'inactive') mediaRecorder.stop()
    isRecording = false
    console.log('⏹ REC STOP')
  } else {
    recordingChunks = []
    const stream  = captureCanvas.captureStream(60)
    const options = { mimeType: 'video/webm;codecs=vp8', videoBitsPerSecond: 60000000 }
    mediaRecorder = new MediaRecorder(stream, options)
    mediaRecorder.ondataavailable = e => {
      if (e.data.size > 0) recordingChunks.push(e.data)
    }
    mediaRecorder.onstop = () => {
      if (!recordingChunks.length) return
      const blob = new Blob(recordingChunks, { type: 'video/webm' })
      const url  = URL.createObjectURL(blob)
      const a    = document.createElement('a')
      a.href     = url
      a.download = 'echolalie_mobile.webm'
      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)
      URL.revokeObjectURL(url)
    }
    mediaRecorder.start(100)
    isRecording = true
    console.log('⏺ REC START')
  }
}

function windowResized() {
  var h = windowHeight
  var w = floor(h * 9 / 16)
  resizeCanvas(w, h)
  captureCanvas.width  = w
  captureCanvas.height = h
}

